1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type ClaimStep = {
19	  op: "claim";
20	  policy: number;
21	  incident: {
22	    cause: string;
23	    damages: Damage[];
24	  };
25	};
26	
27	export type Step = QuoteStep | ClaimStep;
28	
29	export type Customer = {
30	  yearsWithMHPCO: number;
31	};
32	
33	export type Scenario = {
34	  customer: Customer;
35	  steps: Step[];
36	};
37	
38	export type ScenarioResults = {
39	  results: unknown[];
40	};
41	
42	const sum = (amounts: number[]): number =>
43	  amounts.reduce((total, amount) => total + amount, 0);
44	
45	const PROCESSING_FEE = 5;
46	
47	// Binary floating point makes exact multiples land a hair off (100 * 1.1 + 5 =
48	// 115.00000000000001); snap to cent precision so only genuine fractions round.
49	const atCentPrecision = (amount: number): number => Number(amount.toFixed(6));
50	
51	// The office rounds every amount its own way: premiums it collects go up,
52	// payouts it hands out go down.
53	const roundUpInMHPCOsFavour = (amount: number): number =>
54	  Math.ceil(atCentPrecision(amount));
55	
56	const roundDownInMHPCOsFavour = (amount: number): number =>
57	  Math.floor(atCentPrecision(amount));
58	
59	// One entry per insurable type: every fact the office knows about a type lives
60	// here, so adding a type is a single edit.
61	type ItemKind = {
62	  basePremium: number;
63	  insuranceValue: number;
64	  isComponent: boolean;
65	};
66	
67	const ITEM_CATALOGUE: Record<string, ItemKind> = {
68	  sword: { basePremium: 100, insuranceValue: 1000, isComponent: false },
69	  amulet: { basePremium: 60, insuranceValue: 600, isComponent: false },
70	  staff: { basePremium: 80, insuranceValue: 800, isComponent: false },
71	  potion: { basePremium: 40, insuranceValue: 400, isComponent: false },
72	  rune: { basePremium: 25, insuranceValue: 250, isComponent: true },
73	  moonstone: { basePremium: 25, insuranceValue: 250, isComponent: true },
74	};
75	
76	const kindOf = (item: Item): ItemKind => {
77	  const kind = ITEM_CATALOGUE[item.type];
78	
79	  if (!kind) throw new Error(`The MHPCO does not insure "${item.type}" items.`);
80	
81	  return kind;
82	};
83	
84	const basePremiumOf = (item: Item): number => kindOf(item).basePremium;
85	
86	const BLOCK_SIZE = 3;
87	const BLOCK_BASE_PREMIUM = 60;
88	
89	const groupByType = (items: Item[]): Item[][] => {
90	  const itemsByType = new Map<string, Item[]>();
91	
92	  for (const item of items) {
93	    const sameTypeItems = itemsByType.get(item.type);
94	    if (sameTypeItems) sameTypeItems.push(item);
95	    else itemsByType.set(item.type, [item]);
96	  }
97	
98	  return [...itemsByType.values()];
99	};
100	
101	const isComponent = (item: Item): boolean => kindOf(item).isComponent;
102	
103	// A block is a special price for exactly 3 alike components; any other count,
104	// and any main item, is charged per item.
105	const sameTypeBasePremiumOf = (sameTypeItems: Item[]): number =>
106	  sameTypeItems.length === BLOCK_SIZE && isComponent(sameTypeItems[0])
107	    ? BLOCK_BASE_PREMIUM
108	    : sum(sameTypeItems.map(basePremiumOf));
109	
110	const policyBasePremiumOf = (items: Item[]): number =>
111	  sum(groupByType(items).map(sameTypeBasePremiumOf));
112	
113	// Both rate tables stack the same way: every rule whose condition holds
114	// contributes its signed rate, and the rates add. Discounts carry a negative
115	// rate so a table sums without sign-juggling at the call site.
116	type RateRule<Subject> = {
117	  appliesTo: (subject: Subject) => boolean;
118	  rate: number;
119	};
120	
121	const totalRateOf = <Subject>(
122	  rules: RateRule<Subject>[],
123	  subject: Subject,
124	): number =>
125	  sum(
126	    rules.filter(({ appliesTo }) => appliesTo(subject)).map(({ rate }) => rate),
127	  );
128	
129	const HIGH_ENCHANTMENT_THRESHOLD = 5;
130	
131	const isCursed = (item: Item): boolean => item.cursed === true;
132	
133	const isHighlyEnchanted = (item: Item): boolean =>
134	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
135	
136	const ITEM_SURCHARGES: RateRule<Item>[] = [
137	  { appliesTo: isCursed, rate: 0.5 },
138	  { appliesTo: isHighlyEnchanted, rate: 0.3 },
139	];
140	
141	const itemSurchargeRateOf = (item: Item): number =>
142	  totalRateOf(ITEM_SURCHARGES, item);
143	
144	// Item-specific surcharges are charged on that item's own base premium, not on
145	// the policy total.
146	const itemSurchargesOf = (item: Item): number =>
147	  basePremiumOf(item) * itemSurchargeRateOf(item);
148	
149	// Everything outside the item list that a policy-wide modifier may depend on:
150	// who is asking, and where this quote sits in their history with the office.
151	type QuoteContext = {
152	  customer: Customer;
153	  precedingQuotes: number;
154	};
155	
156	const LOYALTY_YEARS_THRESHOLD = 2;
157	
158	const isLoyal = ({ customer }: QuoteContext): boolean =>
159	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
160	
161	const isFollowUpContract = ({ precedingQuotes }: QuoteContext): boolean =>
162	  precedingQuotes > 0;
163	
164	const alwaysApplies = (): boolean => true;
165	
166	const POLICY_MODIFIERS: RateRule<QuoteContext>[] = [
167	  { appliesTo: alwaysApplies, rate: 0.1 }, // first insurance surcharge
168	  { appliesTo: isLoyal, rate: -0.2 },
169	  { appliesTo: isFollowUpContract, rate: -0.15 },
170	];
171	
172	// Policy-wide modifiers are charged on the base premium alone, never on base +
173	// item surcharges: a cursed sword quotes at 100 + 50 + 10 + 5 = 165, where the
174	// 10 is 10 % of 100 rather than of 150.
175	const policyModifierRateOf = (context: QuoteContext): number =>
176	  totalRateOf(POLICY_MODIFIERS, context);
177	
178	const quote = (step: QuoteStep, context: QuoteContext): number => {
179	  const policyBasePremium = policyBasePremiumOf(step.items);
180	  const itemSurcharges = sum(step.items.map(itemSurchargesOf));
181	  const policyModifiers = policyBasePremium * policyModifierRateOf(context);
182	
183	  return roundUpInMHPCOsFavour(
184	    policyBasePremium + itemSurcharges + policyModifiers + PROCESSING_FEE,
185	  );
186	};
187	
188	const DEDUCTIBLE_PER_DAMAGE = 100;
189	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
190	
191	const insuranceSumOf = (items: Item[]): number =>
192	  sum(items.map((item) => kindOf(item).insuranceValue));
193	
194	const REDUCED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
195	const REDUCED_REIMBURSEMENT_SHARE = 0.5;
196	
197	// Heavily enchanted items are notoriously hard to appraise, so the office only
198	// reimburses half of the damage before applying the deductible.
199	const reimbursementShareOf = (item: Item): number =>
200	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
201	    ? REDUCED_REIMBURSEMENT_SHARE
202	    : 1;
203	
204	const payoutForDamage = (damage: Damage, damagedItem: Item): number =>
205	  damage.amount * reimbursementShareOf(damagedItem) - DEDUCTIBLE_PER_DAMAGE;
206	
207	// A claim points at the quote step that issued its policy. Every scenario under
208	// test points at a real quote; rejecting a dangling or non-quote reference is a
209	// deferred validation test, so this narrows without complaining for now.
210	const policyOf = (scenario: Scenario, step: ClaimStep): QuoteStep =>
211	  scenario.steps[step.policy] as QuoteStep;
212	
213	// A damage names the type it hit; the clauses that shape its payout live on the
214	// insured item itself. Every scenario under test damages a covered type;
215	// rejecting a damage the policy does not cover is a deferred validation test,
216	// so this narrows without complaining for now.
217	const damagedItemOf = (policy: QuoteStep, damage: Damage): Item =>
218	  policy.items.find((item) => item.type === damage.itemType) as Item;
219	
220	const claim = (step: ClaimStep, policy: QuoteStep, remainingCap: number) => {
221	  const desiredPayout = roundDownInMHPCOsFavour(
222	    sum(
223	      step.incident.damages.map((damage) =>
224	        payoutForDamage(damage, damagedItemOf(policy, damage)),
225	      ),
226	    ),
227	  );
228	  const payout = Math.min(desiredPayout, remainingCap);
229	
230	  return { payout, remainingCap: remainingCap - payout };
231	};
232	
233	const capOf = (policy: QuoteStep): number =>
234	  insuranceSumOf(policy.items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
235	
236	// A policy's cap is consumed by every claim against it, so what is left has to
237	// survive from one step to the next. The ledger owns that carrying-over: it
238	// starts a policy at its full cap on first sight, and remembers each drawdown.
239	const createCapLedger = () => {
240	  const remainingCapByPolicy = new Map<number, number>();
241	
242	  return {
243	    remainingCapFor: (policyIndex: number, policy: QuoteStep): number =>
244	      remainingCapByPolicy.get(policyIndex) ?? capOf(policy),
245	    recordDrawdown: (policyIndex: number, remainingCap: number): void => {
246	      remainingCapByPolicy.set(policyIndex, remainingCap);
247	    },
248	  };
249	};
250	
251	export const runScenario = (scenario: Scenario): ScenarioResults => {
252	  const capLedger = createCapLedger();
253	
254	  const settleClaim = (step: ClaimStep) => {
255	    const policy = policyOf(scenario, step);
256	    const result = claim(
257	      step,
258	      policy,
259	      capLedger.remainingCapFor(step.policy, policy),
260	    );
261	
262	    capLedger.recordDrawdown(step.policy, result.remainingCap);
263	
264	    return result;
265	  };
266	
267	  // Steps, not quotes: with only quote-then-claim scenarios under test the two
268	  // counts agree. A claim before a quote would make them diverge, and that is
269	  // the deferred test's job to pin down.
270	  const issueQuote = (step: QuoteStep, precedingSteps: number) => ({
271	    premium: quote(step, {
272	      customer: scenario.customer,
273	      precedingQuotes: precedingSteps,
274	    }),
275	  });
276	
277	  return {
278	    results: scenario.steps.map((step, precedingSteps) =>
279	      step.op === "claim" ? settleClaim(step) : issueQuote(step, precedingSteps),
280	    ),
281	  };
282	};
